const BASE_URL = 'https://TU-N8N.ejemplo.com';
const CENTRO = 'tu centro';
const NL = String.fromCharCode(10);

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);
const manana = new Date(hoy.getTime() + 86400000);

function parseFecha(v) {
  if (!v) return null;
  if (v instanceof Date) return new Date(v.getFullYear(), v.getMonth(), v.getDate());
  let s = String(v).trim();
  if (s.length >= 10 && s.charAt(4) === '-') s = s.slice(0, 10);
  let p = s.split('/');
  if (p.length === 3) return new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  p = s.split('-');
  if (p.length === 3) {
    if (p[0].length === 4) return new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
    return new Date(Number(p[2]), Number(p[1]) - 1, Number(p[0]));
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : new Date(d.getFullYear(), d.getMonth(), d.getDate());
}

function fechaTexto(d) {
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return dd + '/' + mm + '/' + d.getFullYear();
}

const base = BASE_URL.endsWith('/') ? BASE_URL.slice(0, -1) : BASE_URL;
const filas = $input.all().map(i => i.json);
const salida = [];

for (const c of filas) {
  const estado = String(c.Estado || 'Pendiente').trim().toLowerCase();
  if (estado.indexOf('cancel') === 0 || estado.indexOf('atendid') === 0) continue;
  const f = parseFecha(c.Fecha);
  if (!f || f.getTime() !== manana.getTime()) continue;
  const email = String(c.Email || '').trim();
  if (!email) continue;
  const id = String(c.ID || '').trim();
  if (!id) continue;
  const nombre = String(c.Paciente || 'paciente').trim() || 'paciente';
  const hora = String(c.Hora || '').trim() || 'la hora acordada';
  const confirmar = base + '/webhook/flowkit-cita?id=' + encodeURIComponent(id) + '&accion=confirmar';
  const cancelar = base + '/webhook/flowkit-cita?id=' + encodeURIComponent(id) + '&accion=cancelar';
  const asunto = 'Recordatorio de cita — ' + fechaTexto(manana) + ' a las ' + hora;
  const cuerpo = [
    'Hola ' + nombre + ':',
    '',
    'Te recordamos tu cita en ' + CENTRO + ' el ' + fechaTexto(manana) + ' a las ' + hora + '.',
    '',
    'Confirma tu asistencia aquí:',
    confirmar,
    '',
    'Si no puedes venir, cancela aquí para que podamos ofrecer el hueco a otra persona:',
    cancelar,
    '',
    'Si ya has confirmado o cancelado, ignora este mensaje.'
  ].join(NL);
  salida.push({ json: { to: email, asunto: asunto, cuerpo: cuerpo, id: id } });
}

return salida;

