const filas = $input.all().map(i => i.json);
const citas = [];

for (const c of filas) {
  const estado = String(c.Estado || 'Pendiente').trim();
  const est = estado.toLowerCase();
  if (est.indexOf('cancel') === 0 || est.indexOf('atendid') === 0) continue;
  const f = parseFecha(c.Fecha);
  if (!f || f.getTime() !== manana.getTime()) continue;
  citas.push({
    hora: String(c.Hora || '').trim(),
    paciente: String(c.Paciente || 'sin nombre').trim(),
    que: String(c.Tratamiento || 'consulta').trim(),
    estado: estado || 'Pendiente',
    email: String(c.Email || '').trim()
  });
}

if (citas.length === 0) return [];

citas.sort((a, b) => String(a.hora).localeCompare(String(b.hora)));
const lineas = citas.map(c => '• ' + (c.hora || '--:--') + ' · ' + c.paciente + ' · ' + c.que + ' · ' + c.estado + (c.email ? '' : ' · SIN EMAIL'));
const texto = 'Agenda de mañana (' + fechaTexto(manana) + '): ' + citas.length + ' cita(s)' + NL + NL + lineas.join(NL) + NL + NL + 'Los pacientes con email han recibido el recordatorio con enlaces para confirmar o cancelar.';

return [{ json: { texto: texto, total: citas.length, fecha: fechaTexto(manana) } }];

const q = ($json.query && typeof $json.query === 'object') ? $json.query : {};
const id = String(q.id || '').trim();
const accion = String(q.accion || '').trim().toLowerCase();
const ok = id.length > 0 && (accion === 'confirmar' || accion === 'cancelar');
const confirmada = accion === 'confirmar';
const nuevo_estado = ok ? (confirmada ? 'Confirmada' : 'Cancelada') : '';
const titulo = ok ? (confirmada ? 'Cita confirmada' : 'Cita cancelada') : 'Enlace no válido';
const mensaje = ok
  ? (confirmada ? 'Gracias. Hemos registrado tu confirmación y avisado al centro.' : 'Hemos registrado la cancelación y avisado al centro para liberar el hueco.')
  : 'El enlace no contiene una cita válida. Si necesitas cambiar tu cita, contacta directamente con el centro.';
const color = ok ? (confirmada ? '#0a7d32' : '#b3261e') : '#6b7280';
const aviso = ok
  ? ('Cita ' + (confirmada ? 'CONFIRMADA' : 'CANCELADA') + ' por el paciente' + String.fromCharCode(10) + 'ID: ' + id + (confirmada ? '' : String.fromCharCode(10, 10) + 'Hueco libre: revisa la agenda y ofrece el hueco a otro paciente.'))
  : ('Enlace de cita no válido' + String.fromCharCode(10) + 'ID: ' + (id || '(vacío)') + ' · Acción: ' + (accion || '(vacía)'));
const html = '<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>' + titulo + '</title></head><body style="margin:0;padding:40px 16px;background:#f6f7f9;font-family:system-ui,-apple-system,Segoe UI,sans-serif;"><main style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px;text-align:center;box-shadow:0 4px 24px rgba(0,0,0,0.08);"><h1 style="margin:0 0 12px;font-size:24px;color:' + color + ';">' + titulo + '</h1><p style="margin:0;font-size:16px;line-height:1.5;color:#333333;">' + mensaje + '</p><p style="margin:24px 0 0;font-size:13px;color:#888888;">Puedes cerrar esta página.</p></main></body></html>';
return [{ json: { ok: ok, id: id, accion: accion, nuevo_estado: nuevo_estado, aviso: aviso, html: html } }];
